		lines = {
			{ "^Palier%. Vous commencez chaque partie avec Horion sacré, et chacun de ses traits rebondit sur 2 ennemis de plus pour ([%-%d%.,]+%%?)%% de ses dégâts%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Absorbe les ([%-%d%.,]+%%?) prochains points de dégâts que vous subissez, ([%-%d%.,]+%%?)%% de vos points de vie maximum%. Relancé dès que le bouclier se brise%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Vos sorts de dégâts sur la durée frappent ([%-%d%.,]+%%?)%% plus vite : plus d'impulsions, et plus de dégâts, dans le même temps%. ([%-%d%.,]+%%?)%% au plus%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Palier%. Chaque soin que vous lancez frappe aussi chaque ennemi à moins de 12 m pour ([%-%d%.,]+%%?)%% des soins en dégâts de Nature%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Palier%. Tir automatique transperce : chaque flèche frappe aussi 1 ennemi derrière sa cible pour ([%-%d%.,]+%%?)%% de ses dégâts%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Vos coups critiques du Sacré vous soignent de ([%-%d%.,]+%%?)%% de vos points de vie maximum, au plus une fois par seconde%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Palier%. Les coups critiques de Châtiment et de Flammes sacrées embrasent leur cible pour ([%-%d%.,]+%%?)%% du coup en 6 s%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Palier%. Vos coups critiques ont ([%-%d%.,]+%%?)%% de chances de lancer un Exorcisme gratuit, au plus une fois par seconde%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Vous soigne de ([%-%d%.,]+%%?), ([%-%d%.,]+%%?)%% de vos points de vie maximum, ([%-%d%.,]+%%?)%. Lancé quand vous passez sous 85%% de vos points de vie%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Vous rend insensible à tous les dégâts pendant ([%-%d%.,]+%%?) s%. Lancé quand vous passez sous 35%% de vos points de vie%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Les ennemis qui brûlent dans votre Consécration subissent ([%-%d%.,]+%%?)%% de dégâts en plus de votre part pendant 3 s%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Palier%. Éclair de givre éclate à l'impact : ([%-%d%.,]+%%?)%% de ses dégâts à chaque ennemi à moins de 5 m de sa cible%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Vos héros (.-) gagnent ([%-%d%.,]+%%?) d'expérience de talents : ([%-%d%.,]+%%?) nouveaux points de talent ! Dépensez%-les à l'armurerie%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Vous protège contre ([%-%d%.,]+%%?) points de dégâts pour chaque ennemi touché, jusqu'à ([%-%d%.,]+%%?), jusqu'à ce qu'il se brise%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^La réduction des dégâts au%-delà du plafond n'est pas perdue : chaque 1%% devient ([%-%d%.,]+%%?)%% de dégâts en plus%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Vos héros (.-) gagnent ([%-%d%.,]+%%?) d'expérience de talents : 1 nouveau point de talent ! Dépensez%-le à l'armurerie%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Augmente tous les dégâts que vous infligez de ([%-%d%.,]+%%?)%% pour chaque tranche de 10%% de réduction des dégâts%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Les ennemis touchés par Cri démoralisant subissent ([%-%d%.,]+%%?)%% de dégâts en plus de votre part pendant 6 s%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Palier%. Vos sorts d'Ombre frappent aussi ce qu'ils touchent pour ([%-%d%.,]+%%?)%% de ses points de vie maximum%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Vous ramène à la vie à la moitié de vos points de vie quand vous mourez%. Contient ([%-%d%.,]+%%?) vies au plus%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
			{ "^Un coup critique vous met en rafale : vos temps de recharge s'écoulent ([%-%d%.,]+%%?)%% plus vite pendant 5 s%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Son temps de recharge commence à la fin de l'insensibilité : ([%-%d%.,]+%%?) s d'un lancement au suivant%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Vous infligez ([%-%d%.,]+%%?)%% de dégâts en plus aux ennemis étourdis, immobilisés, ralentis ou en fuite%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Les temps de recharge de Vague explosive et d'Explosion pyrotechnique sont réduits de ([%-%d%.,]+%%?)%%%.$", "Blast Wave and Pyroblast cooldowns are {v}% shorter.", { "v" } },
			{ "^Palier%. Éclair et Chaîne d'éclairs ont ([%-%d%.,]+%%?)%% de chances de frapper de nouveau gratuitement%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Vous infligez ([%-%d%.,]+%%?)%% de dégâts en plus pour chaque tranche de 10%% de réduction des dégâts%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
			{ "^Un coup fatal vous laisse à ([%-%d%.,]+%%?) de vos points de vie à la place, une fois toutes les ([%-%d%.,]+%%?) s$", "A killing blow leaves you at {heal} health instead, once every {cd} sec", { "heal", "cd" } },
			{ "^Vous infligez ([%-%d%.,]+%%?)%% de dégâts en plus aux ennemis gelés, étourdis, ralentis ou en fuite%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Vos améliorations de dégâts, de hâte, de bouclier et d'épines sont ([%-%d%.,]+%%?) plus puissantes%.$", "Your damage, haste, shield and thorns buffs are {p} stronger.", { "p" } },
			{ "^Palier%. Vos coups critiques lacèrent la cible : elle saigne pour ([%-%d%.,]+%%?)%% du coup en 6 s%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Les temps de recharge de Totem incendiaire et de Totem de magma sont réduits de ([%-%d%.,]+%%?)%%%.$", "Searing and Magma Totem cooldowns are {v}% shorter.", { "v" } },
			{ "^Vous avez gagné ([%-%d%.,]+%%?)%% de dégâts, ([%-%d%.,]+%%?) points de vie maximum et ([%-%d%.,]+%%?) points de vie par seconde%.$", "You have gained {damage}% damage, {health} maximum health and {regen} health per second.", { "damage", "health", "regen" } },
			{ "^Chaque impulsion de Consécration inflige en plus ([%-%d%.,]+%%?)%% de vos points de vie maximum%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Le bouclier de Heurt de bouclier absorbe ([%-%d%.,]+%%?)%% de vos points de vie maximum en plus%.$", "Shield Slam's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^Vos sorts de dégâts sur la durée se cumulent désormais ([%-%d%.,]+%%?) fois sur un même ennemi%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Nova de feu, Totem de magma et Horion de flammes infligent ([%-%d%.,]+%%?)%% de dégâts en plus%.$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^Pendant ([%-%d%.,]+%%?) s, les ennemis qui vous frappent en mêlée subissent ([%-%d%.,]+%%?) points de dégâts%.(.-)$", "For {dur} sec, enemies that hit you in melee take {n} damage.{in_fight}", { "dur", "n", "in_fight" } },
			{ "^Chaque 1%% de réduction des dégâts au%-delà du plafond augmente vos dégâts de ([%-%d%.,]+%%?)%%%.$", "Each 1% of damage reduction past the cap increases your damage by {v}%.", { "v" } },
			{ "^Les ennemis que vous tuez pendant (.-) explosent pour ([%-%d%.,]+%%?) de leurs points de vie max%.$", "Enemies you kill during {spell} explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Totem de magma porte ([%-%d%.,]+%%?)%% plus loin et Totem incendiaire tire sur plus de cibles%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Vous infligez ([%-%d%.,]+%%?)%% de dégâts en plus aux ennemis sous 30%% de leurs points de vie%.$", "You deal {v}% more damage to enemies below 30% health.", { "v" } },
			{ "^Augmente les dégâts infligés aux ennemis sous 30%% de leurs points de vie de ([%-%d%.,]+%%?)%.$", "Increases damage dealt to enemies below 30% health by {p}.", { "p" } },
			{ "^Palier%. Vos coups critiques de Feu enflamment la cible pour ([%-%d%.,]+%%?)%% du coup en 4 s%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Les temps de recharge de Trait de l'ombre et d'Immolation sont réduits de ([%-%d%.,]+%%?)%%%.$", "Shadow Bolt and Immolate cooldowns are {v}% shorter.", { "v" } },
			{ "^Le bouclier de Consécration absorbe ([%-%d%.,]+%%?)%% de vos points de vie maximum en plus%.$", "Consecration's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^Les temps de recharge de Voile mortel et de Drain de vie sont réduits de ([%-%d%.,]+%%?)%%%.$", "Death Coil and Drain Life cooldowns are {v}% shorter.", { "v" } },
			{ "^Chaque sort que vous lancez inflige en plus ([%-%d%.,]+%%?)%% de vos points de vie maximum%.$", "Every spell you cast deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Marteau de la justice inflige ([%-%d%.,]+%%?)%% de dégâts en plus et se recharge plus vite%.$", "Hammer of Justice deals {v}% more damage and recovers faster.", { "v" } },
