			{ "^([%-%d%.,]+%%?) Commence avec (.-) ; chaque niveau propose trois de ses sorts%. ([%-%d%.,]+%%?) points de vie%.$", "{blurb} Starts with {spell}; every level offers three of its spells. {hp} health.", { "blurb", "spell", "hp" } },
			{ "^Les temps de recharge d'Aiguillon perfide et de Suriner sont réduits de ([%-%d%.,]+%%?)%%%.$", "Kidney Shot and Gouge cooldowns are {v}% shorter.", { "v" } },
			{ "^Les ennemis qui meurent sous (.-) explosent pour ([%-%d%.,]+%%?) de leurs points de vie max%.$", "Enemies that die with {spell} on them explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Marteau de courroux a ([%-%d%.,]+%%?)%% de chances de frapper sa cible une nouvelle fois%.$", "Hammer of Wrath has a {v}% chance to strike its target again.", { "v" } },
