			{ "^Palier%. Vos coups critiques font saigner la cible pour ([%-%d%.,]+%%?)%% du coup en 6 s%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Tant que (.-) vous soigne, ([%-%d%.,]+%%?) des dégâts que vous infligez vous soignent aussi$", "While {spell} heals you, {p} of the damage you deal heals you too", { "spell", "p" } },
			{ "^([%-%d%.,]+%%?)%% des dégâts de mêlée que vous infligent les ennemis leur sont renvoyés%.$", "{v}% of the damage enemies deal you in melee is dealt back to them.", { "v" } },
