			{ "^Les ennemis que vous tuez explosent pour ([%-%d%.,]+%%?) de leurs points de vie max%.$", "Enemies you kill explode for {frac} of their max health", { "frac" } },
			{ "^Marteau de la justice inflige en plus ([%-%d%.,]+%%?)%% de vos points de vie maximum%.$", "Hammer of Justice deals an extra {v}% of your maximum health.", { "v" } },
