		lines = {
			{ "^이정표%. 성스러운 일격과 신성한 불꽃의 치명타가 대상을 불태워 6초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 피해를 줍니다%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^이정표%. 모든 도전을 신성 충격을 가지고 시작하며, 각 빛줄기가 적 2명에게 더 튀어 ([%-%d%.,]+%%?)%%의 효과를 줍니다%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^이정표%. 얼음 화살이 충돌하며 쪼개집니다: 대상 주위 5미터 내의 모든 적에게 피해의 ([%-%d%.,]+%%?)%%를 줍니다%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^지속 피해 주문이 ([%-%d%.,]+%%?)%% 빨리 피해를 줍니다: 같은 시간에 더 많은 횟수와 더 많은 피해%. 최대 ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^이정표%. 시전하는 모든 치유가 12미터 내의 모든 적에게도 치유량의 ([%-%d%.,]+%%?)%%만큼 자연 피해를 줍니다%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^다음에 받는 피해 ([%-%d%.,]+%%?)%(최대 생명력의 ([%-%d%.,]+%%?)%%%)을%(를%) 흡수합니다%. 보호막이 깨지면 다시 시전합니다%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^이정표%. 자동 사격이 관통합니다: 화살마다 대상 너머의 적 1명에게도 ([%-%d%.,]+%%?)%%의 효과를 줍니다%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^이정표%. 암흑 주문이 적중한 대상에게 그 대상의 최대 생명력 ([%-%d%.,]+%%?)%%만큼 추가 피해를 줍니다%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^이정표%. 치명타가 대상에게 출혈을 일으켜 6초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 피해를 줍니다%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^(.-)이%(가%) 특성 경험치 ([%-%d%.,]+%%?)을%(를%) 얻었습니다: 새 특성 점수 1점! 무기고에서 사용하세요%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^적중한 적마다 피해 ([%-%d%.,]+%%?)을%(를%) 막는 보호막을 얻으며%(최대 ([%-%d%.,]+%%?)%), 깨질 때까지 유지됩니다%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^(.-)이%(가%) 특성 경험치 ([%-%d%.,]+%%?)을%(를%) 얻었습니다: 새 특성 점수 ([%-%d%.,]+%%?)점! 무기고에서 사용하세요%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^당신의 신성화 속에서 불타는 적은 3초 동안 당신에게서 받는 피해가 ([%-%d%.,]+%%?)%% 증가합니다%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^([%-%d%.,]+%%?) 최대 생명력의 ([%-%d%.,]+%%?)%%인 ([%-%d%.,]+%%?)만큼 치유합니다%. 생명력이 85%% 아래로 떨어지면 시전합니다%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "over", "share", "amount" } },
			{ "^이정표%. 화염 치명타가 대상을 불태워 4초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 피해를 줍니다%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^치명타가 질풍 상태로 만듭니다: 5초 동안 재사용 대기시간이 ([%-%d%.,]+%%?)%% 빨리 회복됩니다%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^([%-%d%.,]+%%?)초 동안 모든 피해에 면역이 됩니다%. 생명력이 35%% 아래로 떨어지면 시전합니다%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^이정표%. 치명타가 대상을 찢어 6초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 출혈 피해를 줍니다%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^상한을 넘는 피해 감소는 낭비되지 않습니다: 1%%마다 피해가 ([%-%d%.,]+%%?)%% 증가합니다%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^사기의 외침에 맞은 적은 6초 동안 당신에게서 받는 피해가 ([%-%d%.,]+%%?)%% 증가합니다%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^용암 토템의 범위가 ([%-%d%.,]+%%?)%% 넓어지고 불타는 토템이 더 많은 대상을 공격합니다%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
