		lines = {
			{ "^Marco%. Você começa toda partida com Choque Sagrado, e cada raio dele salta para mais 2 inimigos com ([%-%d%.,]+%%?)%% do efeito%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Seus feitiços de dano periódico pulsam ([%-%d%.,]+%%?)%% mais rápido: mais pulsos, e mais dano, no mesmo tempo%. No máximo ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Absorve os próximos ([%-%d%.,]+%%?) de dano que você sofrer, ([%-%d%.,]+%%?)%% da sua vida máxima%. Lançado de novo quando o escudo quebra%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Marco%. Toda cura que você lança também atinge todo inimigo a até 12 m com ([%-%d%.,]+%%?)%% da cura como dano de natureza%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Marco%. Seus acertos críticos têm ([%-%d%.,]+%%?)%% de chance de lançar um Exorcismo grátis, no máximo uma vez por segundo%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Marco%. Disparo Automático perfura: cada flecha também atinge 1 inimigo além do alvo com ([%-%d%.,]+%%?)%% do efeito%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Marco%. Acertos críticos de Punição e Fogo Sagrado incendeiam o alvo com ([%-%d%.,]+%%?)%% do acerto ao longo de 6 s%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Seus acertos críticos sagrados curam você em ([%-%d%.,]+%%?)%% da vida máxima, no máximo uma vez por segundo%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Sua classe (.-) ganha ([%-%d%.,]+%%?) de experiência de talento: ([%-%d%.,]+%%?) novos pontos de talento! Gaste%-os no arsenal%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Sua classe (.-) ganha ([%-%d%.,]+%%?) de experiência de talento: 1 novo ponto de talento! Gaste%-o no arsenal%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Marco%. Seta Gélida se estilhaça no impacto: ([%-%d%.,]+%%?)%% do dano em todo inimigo a até 5 m do alvo%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Traz você de volta à vida com metade da vida quando você morre%. Guarda no máximo ([%-%d%.,]+%%?) vidas%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
			{ "^Marco%. Seus acertos críticos de fogo incendeiam o alvo com ([%-%d%.,]+%%?)%% do acerto ao longo de 4 s%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Cura você em ([%-%d%.,]+%%?), ([%-%d%.,]+%%?)%% da sua vida máxima, ([%-%d%.,]+%%?)%. Lançado quando você fica abaixo de 85%% de vida%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Deixa você imune a todo dano por ([%-%d%.,]+%%?) s%. Lançado quando você fica abaixo de 35%% de vida%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Aumenta todo o dano que você causa em ([%-%d%.,]+%%?)%% a cada 10%% de redução de dano que você tem%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Marco%. Seus acertos críticos rasgam o alvo: ele sangra ([%-%d%.,]+%%?)%% do acerto ao longo de 6 s%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Um acerto crítico deixa você em rajada: as recargas voltam ([%-%d%.,]+%%?)%% mais rápido por 5 s%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Você causa ([%-%d%.,]+%%?)%% a mais de dano a inimigos congelados, atordoados, lentos ou fugindo%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Você causa ([%-%d%.,]+%%?)%% a mais de dano a inimigos atordoados, enraizados, lentos ou fugindo%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Inimigos atingidos por Grito Desmoralizante sofrem ([%-%d%.,]+%%?)%% a mais de dano seu por 6 s%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Marco%. Seus feitiços de sombra também atingem o alvo com ([%-%d%.,]+%%?)%% da vida máxima dele%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Totem de Magma alcança ([%-%d%.,]+%%?)%% mais longe e Totem Calcinante dispara em mais alvos%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Marco%. Seus acertos críticos fazem o alvo sangrar ([%-%d%.,]+%%?)%% do golpe ao longo de 6 s%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Redução de dano acima do limite não se perde: cada 1%% vira ([%-%d%.,]+%%?)%% a mais de dano%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^A recarga começa quando a imunidade termina: ([%-%d%.,]+%%?) s de um lançamento ao próximo%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Protege você contra ([%-%d%.,]+%%?) de dano para cada inimigo atingido, até ([%-%d%.,]+%%?), até quebrar%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^Inimigos queimando na sua Consagração sofrem ([%-%d%.,]+%%?)%% a mais de dano seu por 3 s%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Marco%. Raio e Cadeia de Raios têm ([%-%d%.,]+%%?)%% de chance de atingir de novo de graça%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Nova de Fogo, Totem de Magma e Choque Flamejante causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^Você causa ([%-%d%.,]+%%?)%% a mais de dano para cada 10%% de redução de dano que tiver%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
			{ "^Um golpe fatal deixa você com ([%-%d%.,]+%%?) de vida em vez disso, uma vez a cada ([%-%d%.,]+%%?) s$", "A killing blow leaves you at {heal} health instead, once every {cd} sec", { "heal", "cd" } },
			{ "^([%-%d%.,]+%%?)%% do dano corpo a corpo que os inimigos causam a você volta para eles%.$", "{v}% of the damage enemies deal you in melee is dealt back to them.", { "v" } },
			{ "^Seus bônus de dano, aceleração, escudo e espinhos ficam ([%-%d%.,]+%%?) mais fortes%.$", "Your damage, haste, shield and thorns buffs are {p} stronger.", { "p" } },
			{ "^Seus feitiços de dano periódico agora acumulam ([%-%d%.,]+%%?) vezes em um inimigo%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Inimigos que você mata durante (.-) explodem com ([%-%d%.,]+%%?) da vida máxima deles$", "Enemies you kill during {spell} explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Martelo da Justiça causa ([%-%d%.,]+%%?)%% a mais de dano e recarrega mais rápido%.$", "Hammer of Justice deals {v}% more damage and recovers faster.", { "v" } },
			{ "^As recargas do Totem Calcinante e do Totem de Magma são ([%-%d%.,]+%%?)%% menores%.$", "Searing and Magma Totem cooldowns are {v}% shorter.", { "v" } },
			{ "^([%-%d%.,]+%%?) Começa com (.-); cada nível oferece três dos seus feitiços%. ([%-%d%.,]+%%?) de vida%.$", "{blurb} Starts with {spell}; every level offers three of its spells. {hp} health.", { "blurb", "spell", "hp" } },
			{ "^Cada 1%% de redução de dano acima do limite aumenta seu dano em ([%-%d%.,]+%%?)%%%.$", "Each 1% of damage reduction past the cap increases your damage by {v}%.", { "v" } },
			{ "^Por ([%-%d%.,]+%%?) s, inimigos que atingem você corpo a corpo sofrem ([%-%d%.,]+%%?) de dano%.(.-)$", "For {dur} sec, enemies that hit you in melee take {n} damage.{in_fight}", { "dur", "n", "in_fight" } },
			{ "^Aumenta todo o dano que você causa em ([%-%d%.,]+%%?) enquanto um escudo durar%.$", "Increases all damage you deal by {p} while a shield holds.", { "p" } },
			{ "^Aumenta a chance de acerto crítico sua e dos seus mascotes em ([%-%d%.,]+%%?)%%%.$", "Increases your and your pets' critical strike chance by {v}%.", { "v" } },
			{ "^Todo feitiço que você lança causa ([%-%d%.,]+%%?)%% da sua vida máxima a mais%.$", "Every spell you cast deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Você ganhou ([%-%d%.,]+%%?)%% de dano, ([%-%d%.,]+%%?) de vida máxima e ([%-%d%.,]+%%?) de vida por segundo%.$", "You have gained {damage}% damage, {health} maximum health and {regen} health per second.", { "damage", "health", "regen" } },
			{ "^Dá aos seus feitiços ([%-%d%.,]+%%?) de chance de serem lançados duas vezes%.$", "Gives your spells a {p} chance to cast twice.", { "p" } },
			{ "^Você causa ([%-%d%.,]+%%?)%% a mais de dano a inimigos abaixo de 30%% de vida%.$", "You deal {v}% more damage to enemies below 30% health.", { "v" } },
			{ "^O escudo da Consagração absorve ([%-%d%.,]+%%?)%% a mais da sua vida máxima%.$", "Consecration's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^As recargas de Espiral da Morte e Drenar Vida são ([%-%d%.,]+%%?)%% menores%.$", "Death Coil and Drain Life cooldowns are {v}% shorter.", { "v" } },
			{ "^Cada pulso de Consagração causa ([%-%d%.,]+%%?)%% da sua vida máxima a mais%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Aumenta o dano causado a inimigos abaixo de 30%% de vida em ([%-%d%.,]+%%?)%.$", "Increases damage dealt to enemies below 30% health by {p}.", { "p" } },
			{ "^Disparo Automático e Tiro Múltiplo causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Auto Shot and Multi-Shot deal {v}% more damage.", { "v" } },
			{ "^As recargas de Tiro Concussivo e Tiro Mirado são ([%-%d%.,]+%%?)%% menores%.$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^Inimigos que morrem sob (.-) explodem com ([%-%d%.,]+%%?) da vida máxima deles$", "Enemies that die with {spell} on them explode for {frac} of their max health", { "spell", "frac" } },
			{ "^As recargas de Onda de Choque e Ignipancada são ([%-%d%.,]+%%?)%% menores%.$", "Blast Wave and Pyroblast cooldowns are {v}% shorter.", { "v" } },
			{ "^Choque Flamejante e Choque Gélido causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Flame Shock and Frost Shock deal {v}% more damage.", { "v" } },
			{ "^Golpe Flamejante e Onda de Choque causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Flamestrike and Blast Wave deal {v}% more damage.", { "v" } },
			{ "^Atacantes corpo a corpo sofrem ([%-%d%.,]+%%?) do dano que causam a você%.$", "Melee attackers take {p} of the damage they deal you.", { "p" } },
			{ "^Aflige (.-) a até ([%-%d%.,]+%%?) m([%-%d%.,]+%%?): ([%-%d%.,]+%%?) de dano %((.-)%) ao longo de ([%-%d%.,]+%%?) s, em ([%-%d%.,]+%%?) pulsos%.([%-%d%.,]+%%?)$", "Afflicts {targets} within {range} yd{whom}: {total} {school} damage over {secs} sec, in {ticks} ticks.{stack}", { "targets", "range", "whom", "total", "school", "secs", "ticks", "stack" } },
			{ "^Inimigos que você mata explodem com ([%-%d%.,]+%%?) da vida máxima deles$", "Enemies you kill explode for {frac} of their max health", { "frac" } },
			{ "^Martelo da Ira tem ([%-%d%.,]+%%?)%% de chance de atingir o alvo de novo%.$", "Hammer of Wrath has a {v}% chance to strike its target again.", { "v" } },
			{ "^O escudo da Escudada absorve ([%-%d%.,]+%%?)%% a mais da sua vida máxima%.$", "Shield Slam's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^Enquanto (.-) te cura, ([%-%d%.,]+%%?) do dano que você causa também te cura$", "While {spell} heals you, {p} of the damage you deal heals you too", { "spell", "p" } },
			{ "^Aumenta todo o dano e sua chance de acerto crítico em ([%-%d%.,]+%%?)%%%.$", "Increases all damage and your critical strike chance by {v}%.", { "v" } },
			{ "^Escudada causa ([%-%d%.,]+%%?)%% a mais de dano e recarrega mais rápido%.$", "Shield Slam deals {v}% more damage and recovers faster.", { "v" } },
			{ "^Feitiços arcanos e de natureza causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Arcane and Nature spells deal {v}% more damage.", { "v" } },
			{ "^Inimigos mortos por (.-) explodem com ([%-%d%.,]+%%?) da vida máxima deles$", "Enemies {spell} kills explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Enxame de Insetos e Fogo Lunar causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Insect Swarm and Moonfire deal {v}% more damage.", { "v" } },
			{ "^Seus efeitos de dano periódico causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Your damage-over-time effects deal {v}% more damage.", { "v" } },
			{ "^Cada 1%% de redução de dano acima do limite: %+([%-%d%.,]+%%?)%% de dano$", "Each 1% damage reduction past the cap: +{v}% damage", { "v" } },
			{ "^Enquanto um escudo durar, você causa ([%-%d%.,]+%%?)%% a mais de dano%.$", "While a shield holds, you deal {v}% more damage.", { "v" } },
			{ "^Martelo da Justiça causa ([%-%d%.,]+%%?)%% da sua vida máxima a mais%.$", "Hammer of Justice deals an extra {v}% of your maximum health.", { "v" } },
			{ "^As recargas de Golpe nos Rins e Goivar são ([%-%d%.,]+%%?)%% menores%.$", "Kidney Shot and Gouge cooldowns are {v}% shorter.", { "v" } },
			{ "^Sede de Sangue e Redemoinho causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Bloodthirst and Whirlwind deal {v}% more damage.", { "v" } },
			{ "^As recargas de Punição e Fogo Sagrado são ([%-%d%.,]+%%?)%% menores%.$", "Smite and Holy Fire cooldowns are {v}% shorter.", { "v" } },
			{ "^Seus feitiços de dano periódico pulsam ([%-%d%.,]+%%?)%% mais rápido$", "Your damage over time spells tick {v}% faster", { "v" } },
			{ "^As recargas de Seta Sombria e Imolar são ([%-%d%.,]+%%?)%% menores%.$", "Shadow Bolt and Immolate cooldowns are {v}% shorter.", { "v" } },
			{ "^Golpe Sinistro e Eviscerar causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Sinister Strike and Eviscerate deal {v}% more damage.", { "v" } },
			{ "^([%-%d%.,]+%%?)%% de chance de qualquer feitiço acertar duas vezes%.$", "{v}% chance for any spell to strike twice.", { "v" } },
			{ "^Aumenta o dano causado a inimigos controlados em ([%-%d%.,]+%%?)%.$", "Increases damage dealt to crowd-controlled enemies by {p}.", { "p" } },
			{ "^Atacantes corpo a corpo sofrem ([%-%d%.,]+%%?) do dano que causam$", "Melee attackers take {p} of the damage they deal", { "p" } },
			{ "^Tiro Múltiplo e Saraivada causam ([%-%d%.,]+%%?)%% a mais de dano%.$", "Multi-Shot and Volley deal {v}% more damage.", { "v" } },
			{ "^(.-) fazem os inimigos sofrerem ([%-%d%.,]+%%?) a mais de dano por ([%-%d%.,]+%%?) s$", "{hits} leave enemies taking {v} more damage for {s} sec", { "hits", "v", "s" } },
