	tr = {
		names = {
			["Yakın Dövüş"] = "Melee",
		},
		lines = {
			{ "^Dönüm noktası%. Kullandığın her iyileştirme ayrıca 12 m içindeki her düşmana iyileştirmenin %%([%-%d%.,]+%%?)'i kadar Doğa hasarı verir%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Dönüm noktası%. Her oyuna Holy Shock ile başlarsın ve her atışı 2 düşmana daha kendi hasarının %%([%-%d%.,]+%%?)'i kadar sıçrar%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Zamanla hasar veren büyülerin %%([%-%d%.,]+%%?) daha hızlı tikler: aynı sürede daha fazla tik ve daha fazla hasar%. En fazla %%([%-%d%.,]+%%?)%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Dönüm noktası%. Auto Shot deler: her ok hedefinin ardındaki 1 düşmana daha kendi hasarının %%([%-%d%.,]+%%?)'i kadar vurur%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Dönüm noktası%. Smite ve Holy Fire kritik vuruşları hedeflerini 6 sn boyunca vuruşun %%([%-%d%.,]+%%?)'i kadar tutuşturur%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Dönüm noktası%. Kritik vuruşlarının bedava bir Exorcism fırlatma şansı %%([%-%d%.,]+%%?), saniyede en fazla bir kez%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Dönüm noktası%. Frostbolt çarpınca parçalanır: hasarının %%([%-%d%.,]+%%?)'i hedefinin 5 m içindeki her düşmana%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Kutsal kritik vuruşların seni azami canının %%([%-%d%.,]+%%?)'i kadar iyileştirir, saniyede en fazla bir kez%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Dönüm noktası%. Gölge büyülerin vurduğu hedefe ayrıca azami canının %%([%-%d%.,]+%%?)'i kadar hasar verir%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^([%-%d%.,]+%%?) sn boyunca seni tüm hasara karşı bağışık kılar%. Canın %%35'in altına düşünce kullanılır%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Dönüm noktası%. Ateş kritik vuruşların hedefi 4 sn boyunca vuruşun %%([%-%d%.,]+%%?)'i kadar tutuşturur%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Sersemlemiş, sabitlenmiş, yavaşlamış veya kaçan düşmanlara %%([%-%d%.,]+%%?) daha fazla hasar verirsin%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Aldığın sonraki ([%-%d%.,]+%%?) hasarı emer, azami canının %%([%-%d%.,]+%%?)'i%. Kalkan kırılınca yeniden kullanılır%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Demoralizing Shout'un vurduğu düşmanlar 6 sn boyunca senden %%([%-%d%.,]+%%?) daha fazla hasar alır%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Dönüm noktası%. Kritik vuruşların hedefi yarar: 6 sn boyunca vuruşun %%([%-%d%.,]+%%?)'i kadar kanar%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Dönüm noktası%. Lightning Bolt ve Chain Lightning'in bedavaya yeniden vurma şansı %%([%-%d%.,]+%%?)%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^(.-) kahramanların ([%-%d%.,]+%%?) yetenek deneyimi kazandı: 1 yeni yetenek puanı! Cephanelikte harca%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Donmuş, sersemlemiş, yavaşlamış veya kaçan düşmanlara %%([%-%d%.,]+%%?) daha fazla hasar verirsin%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^(.-) kahramanların ([%-%d%.,]+%%?) yetenek deneyimi kazandı: ([%-%d%.,]+%%?) yeni yetenek puanı! Cephanelikte harca%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Bir kritik vuruş seni coşturur: 5 sn boyunca bekleme süreleri %%([%-%d%.,]+%%?) daha hızlı dolar%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Seni ([%-%d%.,]+%%?) iyileştirir, azami canının %%([%-%d%.,]+%%?)'i, ([%-%d%.,]+%%?)%. Canın %%85'in altına düşünce kullanılır%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Dönüm noktası%. Kritik vuruşların hedefi 6 sn boyunca vuruşun %%([%-%d%.,]+%%?)'i kadar kanatır%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Consecration'ında yanan düşmanlar 3 sn boyunca senden %%([%-%d%.,]+%%?) daha fazla hasar alır%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Magma Totem %%([%-%d%.,]+%%?) daha uzağa ulaşır ve Searing Totem daha fazla hedefe ateş eder%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Sınırı aşan hasar azaltma boşa gitmez: her %%1'i %%([%-%d%.,]+%%?) daha fazla hasara dönüşür%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Consecration'ın her tiki ek olarak azami canının %%([%-%d%.,]+%%?)'i kadar hasar verir%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
