			{ "^Vurulan her düşman için ([%-%d%.,]+%%?) hasara karşı korur, en fazla ([%-%d%.,]+%%?), kırılana kadar%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^Zamanla hasar veren büyülerin artık bir düşman üzerinde ([%-%d%.,]+%%?) kez birikiyor%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Sahip olduğun her %%10 hasar azaltma için %%([%-%d%.,]+%%?) daha fazla hasar verirsin%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
