			{ "^Öldürücü bir darbe seni bunun yerine ([%-%d%.,]+%%?) canla bırakır, ([%-%d%.,]+%%?) sn'de bir kez$", "A killing blow leaves you at {heal} health instead, once every {cd} sec", { "heal", "cd" } },
